#ifndef BRAINCHOPC_WEBGL2_REF_CONV_H
#define BRAINCHOPC_WEBGL2_REF_CONV_H

#include <stddef.h>

/*
 * A scalar reference for layer 0, over ONE z slice.
 *
 * WHY THIS EXISTS. Bringing this backend up had to answer "does the GPU
 * convolution agree with the CPU", and the obvious way -- call mn_conv_first --
 * is not available inside the wasm module for two reasons. It is `static`
 * inside meshnet_cpu.c, generated by MN_DEFINE_CONV, and project policy forbids
 * restructuring that macro or anything that would force the compiler to emit it
 * as a named function; and its output is the whole 256^3 x 16 volume, 1.07 GiB
 * as f32, which a browser module sized for GPU-resident activations has no
 * reason to be able to hold.
 *
 * So the comparison is done a slice at a time against this, and this is in turn
 * checked against mn_conv_first over the full volume by
 * test/webgl2_conv_first_check.c, which builds natively and CAN include
 * meshnet_cpu.c directly. One implementation, two callers, so the thing being
 * compared against the GPU is the same thing that was compared against the
 * project's specification.
 *
 * ACCUMULATION ORDER matches MN_DEFINE_CONV exactly, which is the point. The
 * CPU walks whole (dz, dy) rows, skipping any that fall outside the volume, and
 * within a row walks dx; the included taps are therefore visited in ascending
 * tap order, which is what the loop below does. A different order would still
 * be "correct" and would still disagree in the last bits, turning a plumbing
 * check into a rounding argument.
 *
 * The kernel is meshnet_cpu_pack_kernel's layout with input_channels == 1, so
 * ((tap * 1) + 0) * cs + oc collapses to tap * cs + oc.
 */
static void bc_webgl2_ref_conv_first_slice(const float *input,
		const float *kernel, int dilation, int z, int dim, int cs, float *out) {
	for (int y = 0; y < dim; y++) {
		for (int x = 0; x < dim; x++) {
			float *acc = out + ((size_t)y * dim + x) * cs;
			for (int c = 0; c < cs; c++) acc[c] = 0.0f;
			int tap = 0;
			for (int dz = -1; dz <= 1; dz++)
			for (int dy = -1; dy <= 1; dy++)
			for (int dx = -1; dx <= 1; dx++) {
				int sz = z + dz * dilation;
				int sy = y + dy * dilation;
				int sx = x + dx * dilation;
				if (sz >= 0 && sz < dim && sy >= 0 && sy < dim &&
						sx >= 0 && sx < dim) {
					float v = input[((size_t)sz * dim + sy) * dim + sx];
					const float *w = kernel + (size_t)tap * cs;
					for (int c = 0; c < cs; c++) acc[c] += v * w[c];
				}
				tap++;
			}
		}
	}
}

#endif
